INSERT INTO `about_content` (`ID`, `section`, `title`, `description`, `about_img`, `status`, `created_date`, `updated_date`) VALUES
	(5, 'History', '1571', 'Captain Juan de Salcedo discovered ad founded Biñan at the end of June 1571, a month after Miguel Lopez de Legaspi established Manila when he explored the largest freshwater lake in the Philippines and second in Asia (Laguna de Bay)', '1722563762_58dbf047f10d1d2cfc2c.png', 'ACTIVE', '2024-08-02 01:56:02', '2024-08-02 09:56:02'),
	(6, 'History', '1688', 'When the seat of the provincial government of the Provincia de Laguna de Bay was moved from Bay to Pagsanjan in 1688, Biñan separated from its mother town Tabuco (now known as the city of Cabuyao)', '1722563794_34aed21fdb77504e305a.png', 'ACTIVE', '2024-08-02 01:56:34', '2024-08-02 09:56:34'),
	(7, 'History', '1791', 'In 1971, during the time of Pablo Faustino, Santa Rosa separated from Biñan. The following year, January 15 Sta. Rosa de Lima was established and became an independent town.', '1722563887_fbd05bba358d74f19118.jpg', 'ACTIVE', '2024-08-02 01:57:30', '2024-08-02 01:58:07'),
	(8, 'History', '1869', 'Biñan is nationally recognized in the books related to the biography of Jose Rizal, the country\'s national hero. It was n June 1869 when Jose Rizal as a young boy went to Biñan wit his brother Paciano. They proceeded to his aunt\'s house near the town proper where they were to be lodged.', '1722563907_d67c507b7939d4ce3efd.jpg', 'ACTIVE', '2024-08-02 01:58:27', '2024-08-02 09:58:27'),
	(9, 'History', '1869', 'Here, his first formal education was entrusted to Maestro Justiniano Aquino Cruz who after a year and a hald of tutelage advised young Rizal to continue hiher education in Mannila. In honor of Jose Rizal a plaque of recognition was bestowed on the house where he stayed at. A monument now stands at the center of Biñan\'s town plaza in recognition of Biñan\'s affiliation to Rizal.', '1722563925_54f03ce817d85fa00ca2.jpg', 'ACTIVE', '2024-08-02 01:58:45', '2024-08-02 02:40:07'),
	(10, 'History', '2010', 'by the virtue of the Republic Act No. 9740, Biñan became a component city after its voters accepted the ratification in the plebiscite. It became the 4th city in the province and 139th in the Philippines.\r\n', '1748478676_80af2d5fd9b33d3bd0dc.png', 'ACTIVE', '2024-08-02 02:40:29', '2025-05-29 08:31:23'),
	(16, 'Home Page', 'History', 'Discover the rich history of Biñan here.', NULL, 'ACTIVE', '2024-08-02 06:20:34', '2025-05-14 00:46:26'),
	(21, 'Content', 'Mission', '<p class="ql-align-justify"><strong>The leadership of the City Biñan is committed to exercise its mandate to:</strong></p><ul><li class="ql-indent-1 ql-align-justify">Promote social order and ensure public safety;</li><li class="ql-indent-1 ql-align-justify">Enhance economic prosperity through job generation, manpower and skills development, encourage and support local industries and their expansion;</li><li class="ql-indent-1 ql-align-justify">Guarantee social justice by way of ensuring basic services and equal opportunities;</li><li class="ql-indent-1 ql-align-justify">Deliver accessible and quality health care services;</li><li class="ql-indent-1 ql-align-justify">Protect and maximize the utilization of environment and natural resources towards the attainment of a disaster-resilient community;</li><li class="ql-indent-1 ql-align-justify">Ensure access to free and quality education to prepare our youth to be globally competitive;</li><li class="ql-indent-1 ql-align-justify">Support gender sensitivity, responsiveness and equality;</li><li class="ql-indent-1 ql-align-justify">Provide modern and needed infrastructure facilities;</li><li class="ql-indent-1 ql-align-justify">Preserve, conserve and nurture its cultural, historical and artistic heritage towards sustainable tourism; and</li><li class="ql-indent-1 ql-align-justify">Increase collection efficiency through reasonable taxes, fees and charges, and ensure sound fiscal management.</li></ul>', NULL, 'ACTIVE', '2024-08-02 06:23:58', '2026-02-12 13:40:32'),
	(22, 'Content', 'Vision', '<p class="ql-align-justify">A modern and developed City where its responsible people are proud of their cultural, historical and artistic heritage; enjoy peace and security, economic stability, social justice, preserved environment, accessible quality education, responsive social services, well-planned infrastructure facilities all anchored on good governance thus making the City of Biñan the Premier Heritage and Trade Capital of the South, the best place to live, work and visit.</p>', '1722563728_f91efddb8e7ac4545906.png', 'ACTIVE', '2024-08-02 01:55:28', '2026-02-12 13:37:49'),
	(23, 'Content', 'Quality Policy', '<p class="ql-align-justify">We are committed to implement the Quality Management System and together with the stakeholders are committed to empower the people to develop sustainable and economic enterprises.</p><p class="ql-align-justify">We visualize a modern humanely developed City of Biñan, where its people enjoy peace and security, economic stability, social justice, a well-preserved environment, accessible quality education, responsive social services and modernized infrastructure facilities all anchored on good governance.</p><p class="ql-align-justify">To achieve all these, the management of the City Government of Biñan shall:</p><ul><li class="ql-align-justify">Empower our personnel to resolve problems and initiate improvements;</li><li class="ql-align-justify">Comply with all applicable legal and other statutory requirements;</li><li class="ql-align-justify">Initiate dynamic and systematic response/s to our internal and external customers’ needs; process performance.</li><li class="ql-align-justify">Conduct periodic reviews by the management on quality objectives and targets to monitor and keep track of the progress of the programs and ensure continued suitability of the established QMS in relation to our quality.</li></ul><p class="ql-align-justify">The City Government of Biñan shall ensure the effective implementation and maintenance of the Quality Management System and compliance to the requirements of ISO 9001:2015, as well as ensuring its sustainability and availability to all interested parties within the confines of applicable laws.</p>', '1722577197_b544c55a9dac11b5c462.png', 'ACTIVE', '2024-08-02 05:39:57', '2026-02-12 13:42:13'),
	(24, 'Emergency Hotlines', 'CDRRMO (City Disaster Risk Reduction and Management Office)', '<p class="ql-align-right"><strong>SMART:</strong>&nbsp;0908-891-9711</p><p class="ql-align-right"><strong>GLOBE:&nbsp;</strong>0917-120-8911</p><p class="ql-align-right"><strong>INTELCO:</strong>&nbsp;(049) 513-9111</p><p class="ql-align-right"><strong>PLDT: </strong>(049) 523-9111</p>', NULL, 'ACTIVE', '2025-08-01 09:13:04', '2026-01-14 10:01:25'),
	(25, 'Emergency Hotlines', 'BCH (Biñan City Hospital)', '<p class="ql-align-right"><strong>INTELCO: </strong>(049) 511-4119<span class="ql-cursor">﻿﻿</span></p>', NULL, 'ACTIVE', '2025-08-01 09:13:04', '2026-01-14 10:01:37'),
	(26, 'Emergency Hotlines', 'PNP Biñan (Philippine National Police Biñan)', '<p class="ql-align-right"><strong>SMART:</strong> 0998-598-5631</p><p class="ql-align-right"><strong>GLOBE:</strong> 0916-261-9833</p><p class="ql-align-right"><strong>INTELCO: </strong>(049) 513-5113</p>', NULL, 'ACTIVE', '2025-08-01 09:13:04', '2026-01-14 10:01:46'),
	(27, 'Emergency Hotlines', 'BFP Biñan (Bureau of Fire Protection Biñan)', '<p class="ql-align-right"><strong>INTELCO:</strong> (049) 511-9111</p><p class="ql-align-right"><strong>DITO:</strong> 0992-419-3585</p>', NULL, 'ACTIVE', '2025-08-01 09:13:04', '2026-01-14 10:01:53');
