INSERT INTO `jobs` (`id`, `title`, `description`, `company`, `type`, `publication_date`, `email`, `status`, `created_date`, `updated_date`) VALUES
	(3, 'IT Specialist', '<p class="ql-align-justify">An <strong><em>IT Specialist</em></strong> at a leading technology company like Microsoft plays a critical role in maintaining and optimizing the organization\'s digital infrastructure. They are responsible for managing and supporting hardware, software, networks, and security systems to ensure smooth and secure operations across all departments. This role involves troubleshooting technical issues, implementing system upgrades, and collaborating with cross-functional teams to develop and deploy innovative IT solutions. With a strong focus on reliability, performance, and cybersecurity, the <strong><em>IT Specialist</em></strong> helps drive Microsoft’s mission to empower every person and organization on the planet to achieve more through seamless technology support and innovation.</p>', 'Microsoft', 'Full Time', '2025-07-11', 'mscompany@outlook.com', 'ACTIVE', '2025-07-11 10:11:33', '2025-07-31 09:42:16'),
	(4, 'Marketing Coordinator', '<p class="ql-align-justify">BrightWave Advertising is seeking a creative and detail-oriented Marketing Coordinator to support campaign planning and execution. Responsibilities include market research, managing social media content calendars, coordinating with designers, and analyzing campaign performance metrics.</p>', 'BrightWave Advertising', 'Full Time', '2025-07-11', 'careers@brightwaveads.com', 'ACTIVE', '2025-07-11 10:18:03', '2025-07-31 09:46:19'),
	(5, 'Human Resource Assistant', '<p class="ql-align-justify">Zenith is hiring an HR Assistant to help manage employee records, schedule interviews, and assist with onboarding. The ideal candidate is organized, approachable, and has basic knowledge of labor laws and HR software tools.</p>', 'Zenith Staffing Solutions', 'Part Time', '2025-07-11', 'hr@zenithstaffing.com', 'ACTIVE', '2025-07-11 10:18:33', '2025-07-31 09:45:18'),
	(6, 'Customer Service Representative', '<p class="ql-align-justify">We are looking for a Customer Service Representative to handle phone, chat, and email inquiries from clients. Duties include resolving delivery issues, updating account info, and providing product information. Strong communication and problem-solving skills are essential.</p>', 'Pacifica Water Delivery Services', 'Full Time', '2025-07-11', 'support@pacificawater.com', 'ACTIVE', '2025-07-11 10:19:02', '2025-07-31 09:46:13'),
	(7, 'Sales Associate', '<p class="ql-align-justify">Join our dynamic retail team! As a Sales Associate, you’ll assist customers, manage inventory, and ensure a pleasant shopping experience. Experience in fashion retail is a plus but not required—just bring a friendly attitude and a passion for style.</p>', 'TrendHouse Apparel', 'Part Time', '2025-07-11', 'jobs@trendhousefashion.com', 'ACTIVE', '2025-07-11 10:19:23', '2025-07-31 09:45:10'),
	(8, 'Administrative Officer', '<p class="ql-align-justify">SouthBay Logistics is seeking a reliable Administrative Officer to oversee office tasks such as scheduling, filing, and handling correspondence. The role requires proficiency in Microsoft Office, excellent time management skills, and a professional demeanor.</p>', 'SouthBay Logistics', 'Full Time', '2025-07-11', 'admin@southbaylogistics.com', 'ACTIVE', '2025-07-11 10:19:54', '2025-07-31 09:45:57'),
	(9, 'Graphic Designer', '<p class="ql-align-justify">Canvas &amp; Co. is looking for a freelance Graphic Designer to produce visual assets for branding, social media, and print. Proficiency in Adobe Creative Suite is required. Must have a strong portfolio and be comfortable working with tight deadlines.</p>', 'Canvas & Co. Studio', 'Full Time', '2025-07-11', 'hello@canvasnco.com', 'ACTIVE', '2025-07-11 10:20:13', '2025-07-31 09:45:48'),
	(10, 'Project Manager', '<p class="ql-align-justify"><strong><em>Microsoft Technologies</em></strong> is seeking a detail-oriented and experienced Project Manager to lead cross-functional teams in the delivery of software, cloud, and enterprise projects. You will be responsible for planning, scheduling, budgeting, risk management, and ensuring timely completion of deliverables. Strong leadership, communication, and knowledge of Agile or Scrum methodologies are essential.</p>', 'Microsoft', 'Full Time', '2025-07-11', 'careers@microsoft-tech.com', 'ACTIVE', '2025-07-11 10:20:44', '2025-07-31 09:45:40');
