INSERT INTO `mayor_content` (`ID`, `section`, `mayor_name`, `content`, `mayor_img`, `created_date`, `updated_date`, `status`) VALUES
	(4, 'Awards', '', '<p><strong>Awards that the mayor have received are listed:</strong></p><ul><li class="ql-align-justify">Lorem ipsum dolor sit amet, consectetur adipiscing elit.</li><li class="ql-align-justify">Etiam id erat ut quam consequat vestibulum.</li><li class="ql-align-justify">Curabitur a mi sit amet est consequat suscipit ac vitae turpis.</li><li class="ql-align-justify">In ultricies augue et libero aliquet ultricies.</li><li class="ql-align-justify">Sed sit amet augue quis lorem tempor efficitur.</li></ul>', '[]', '2024-07-11 01:14:31', '2025-07-14 22:36:02', 'ACTIVE'),
	(5, 'Years Service', '', '<p>Normal text</p><p><strong>Bold</strong></p><p><strong><u>Underlined</u></strong> <u>without bold</u></p><p><em>Italic</em></p>', '', '2024-07-11 01:49:33', '2024-07-11 11:12:18', 'ACTIVE'),
	(6, 'Gallery', '', '<p>Lorem <em>ipsum dolor sit amet,</em> consectetur adipiscing elit, sed do eiusmod tempor incididunt ut labore et dolore magna aliqua. Ut enim ad minim veniam, quis nostrud exercitation ullamco laboris nisi ut aliquip ex ea commodo consequat. Duis aute irure dolor in reprehenderit in voluptate velit esse cillum dolore eu fugiat nulla pariatur. Excepteur sint occaecat cupidatat non proident, sunt in culpa qui officia deserunt mollit anim id est laborum.</p><ol><li>Lorem ipsum dolor sit amet, consectetur adipiscing elit, sed do eiusmod tempor incididunt ut labore et dolore magna aliqua.</li><li>Lorem ipsum dolor sit amet, consectetur adipiscing elit, sed do eiusmod tempor incididunt ut labore et dolore magna aliqua.</li><li>Lorem ipsum dolor sit amet, consectetur adipiscing elit, sed do eiusmod tempor incididunt ut labore et dolore magna aliqua.</li></ol>', '["1752539275_f7c514e3b71ad925591b.jpg","1752539275_cc5d2e194bb2c24a824e.jpg","1752539275_461564b96f4fa7ceb020.jpg","1752539275_ea1d0a840cec5bba9fd2.jpg","1752539275_fa6c311f39c9c860e58d.jpg"]', '2024-07-11 02:03:14', '2025-07-15 00:27:55', 'ACTIVE'),
	(7, 'Personal Data', 'Hon. Angelo "Gel" B. Alonte, MPA', '<p class="ql-align-justify">The <strong>Mayor’s Office</strong> has been in touch with the elderly and the sick for aid in their current conditions. His “Kalinga ng AnGEL” has been a long-standing program for cancer survivors, not only providing monetary assistance, but going house to house to cater to their spiritual needs. The office has reached out with various initiatives such as the “Munting AnGEL” which has provided free vaccinations, ophthalmologic consults, free eye glasses and dental care to name a few. Proving to be no one-trick pony, the Mayor has been an avid supporter and beacon in the realm of sports, providing avenues for healthy competition amongst other sports enthusiasts like himself. He has shown that sports bring the community together and that with the right mindset and support system, each aspiring Biñanense can reach the top. Also, educational scholarships have been offered to many to make their dream a reality. This has been his success, taking pride in each individual and each part of the City of Biñan. An undertaking which is no easy task yet the Mayor has clearly put into heart. The community remains hopeful for more of what he has to offer and as he promises to live up to these expectations.</p><p><strong><u>#TatakGEL</u></strong></p><p><br></p>', '["1752736418_1ff67fd278268a7aaae6.png"]', '2024-07-11 02:15:45', '2025-07-17 07:13:38', 'ACTIVE'),
	(8, 'Home Page', '', '<p class="ql-align-justify"><u>Lorem ipsum dolor sit amet, consectetur adipiscing elit.</u> <em>Sed do eiusmod tempor incididunt ut labore et dolore magna aliqua. </em><strong><em><u>“Kalinga ng AnGEL</u>”</em></strong><em> est programmatibus diu stans pro cancer superstitibus</em>, non solum auxilio pecuniario praebendo, sed etiam domum euntes ad necessitatibus spiritualibus occurrendum. Officium pervenit ad varias inceptas sicut<strong> <em><u>“Munting AnGEL,”</u></em> </strong>quae vaccinationes gratuitas, consultationes ophthalmologicas, oculorum vitra gratuita, et curationes dentales inter alia praebuit.</p>', '["1752560720_0dff09b7b49027edfdc8.png"]', '2024-07-11 02:43:37', '2025-07-15 06:25:20', 'ACTIVE');
INSERT INTO `officials_content` (`ID`, `off_name`, `off_position`, `img_loc`, `created_date`, `updated_date`, `ranking`, `years_of_service`, `personal_data`, `awards`, `carouselimages`, `status`) VALUES
	(30, 'Atty. Walfredo "Arman" R. Dimaguila Jr.', 'CONGRESS', '1753922986_227ce8d1fc7ea674144d.jpg', '2025-07-21 07:33:36', '2025-08-04 02:13:01', NULL, '<p>-</p>', '<p>-</p>', '<p>-</p>', NULL, 'ACTIVE'),
	(32, 'Hon. Jonalina "Dada" A. Reyes', 'CITY VICE MAYOR', '1753083396_fbe1c39b9f3ce1c4ec9d.jpg', '2025-07-21 07:36:36', NULL, NULL, '<p>-</p>', '<p>-</p>', '<p>-</p>', '', 'ACTIVE'),
	(33, 'Hon. Libunero "Jedi" O. Alatiit', 'CITY COUNCILOR', '1753083427_5a98d81117130135ac4c.jpg', '2025-07-21 07:37:07', '2025-07-31 00:44:19', 1, '<ul><li><strong>Elected as Biñan City Councilor</strong> for the <strong>first term in 2019</strong></li><li><strong>Re-elected for a second term in 2022</strong></li><li><strong>Currently serving</strong> in his third consecutive term as of <strong>2025</strong></li></ul>', '<p class="ql-align-justify"><strong>Councilor Libunero “Jedi” O. Alatiit </strong>was born on November 8, 1988, in Malaban, Biñan, Laguna. He is the second of five children of Mr. Libunero A. Alatiit and Mrs. Mildred O. Alatiit, both of whom came from humble beginnings but are known for their dedicated service in the community. From a young age, he learned responsibility and the value of compassion and service to others. He is the husband of Diana Limongco Alatiit and the father of Alamih Caelum L. Alatiit. He is also a member of the Seventh-day Adventist Church. In terms of education, he took two years of Psychology, spent five years studying Physical Therapy, and completed his degree in AB Political Science in 2014—showcasing his continuous pursuit of knowledge in preparation for serving others more effectively.</p>', '<ul><li>Ordinance for <strong>Persons with Disabilities (PWDs)</strong></li><li><strong>COVID-19 Contact Tracing App</strong> – <em>Bind 360</em></li><li><strong>Free medical examination and laboratory tests</strong> for first-time job seekers</li><li><strong>Insurance program</strong> for workers in high-risk industries</li><li><strong>Discounted Laboratory Program</strong> – for more affordable medical tests for Biñan residents</li></ul><p><br></p>', '1753681716_9659a4e4d6b6fafa3a50.jpg,1753681716_3b78f5f7e83890afd484.jpg,1753681716_be28ffa2d2b605634d82.jpg', 'ACTIVE'),
	(34, 'Hon. Geminiano "Manong" B. Catalon', 'ABC PRESIDENT', '1753083832_24114289cdde9c5b51b5.jpg', '2025-07-21 07:43:52', '2025-07-31 00:43:28', NULL, '<ul><li><strong>1970s</strong> – Appointed as SK Chairman</li><li><strong>1988–present</strong> – President, San Francisco Tricycle Operators and Drivers Association (SANFRATODA)</li><li><strong>1994–2013</strong> – Barangay Kagawad, Brgy. San Francisco (16 years)</li><li><strong>1998–present</strong> – President, Biñan Federated Tricycle Operators and Drivers Association (BFETODA)</li><li><strong>2000–2005</strong> – President, Kaisahan ng Samahang Magta-tricycle sa Buong Laguna</li><li><strong>2013–present</strong> – Punong Barangay, Brgy. San Francisco</li><li><strong>2023–present</strong> – President, Liga ng mga Barangay sa Lungsod ng Biñan</li></ul>', '<p class="ql-align-justify"><strong>Geminiano B. Catalon</strong> was born on September 16, 1956, the youngest of six siblings to parents Amando Catalon and Angela Belen, both residents of Barangay San Francisco, Biñan City, Laguna. He completed his elementary education at Doña Aurora Elementary School and secondary education at Biñan National School of Arts and Trades. He pursued college studies at the University of the Philippines – Los Baños with the help of a priest who offered him a scholarship. However, his college journey was cut short due to the untimely passing of his benefactor.</p><p>Coming from a humble and ordinary family, Geminiano was not able to finish his higher education, but he worked hard to support his family and later raised two daughters:</p><ul><li><strong>Miraquel M. Catalon</strong> – graduated with a degree in BS Commerce, Major in Business Administration, from the University of Santo Tomas.</li><li><strong>Rose Ann M. Catalon</strong> – also graduated from the University of Santo Tomas with a degree in BS Commerce, Major in Marketing Management.</li></ul><p><br></p>', '<ul><li><strong>2017</strong> – Finalist, Regional Outstanding Barangay Nutrition Committee</li><li><strong>2017</strong> – Finalist, City Most Outstanding Barangay Nutrition Committee</li><li><strong>2018</strong> – Regional Awardee, Drug-Cleared Barangay</li><li><strong>2024</strong> – Regional Awardee, Seal of Good Local Governance (SGLG)</li><li><strong>2025</strong> – National Awardee, Most Outstanding Barangay for Plans, Programs, and Project Implementation</li><li><strong>2025</strong> – National Awardee, Most Outstanding Punong Barangay of the Year</li></ul><p><br></p>', '1753083832_dbd45a7d0f85da555bfc.jpg,1753083832_9c042461b3e61fadeada.jpg,1753083832_444e836b88cdc53ce34b.jpg', 'ACTIVE'),
	(35, 'Hon. Alonzo Kyne S. Garcia', 'SK FEDERATION PRESIDENT', '1753083853_93342f658f89fef63002.jpg', '2025-07-21 07:44:13', '2025-07-31 00:43:42', NULL, '<ul><li><strong>Sangguniang Kabataan (SK) Chairperson</strong>, Barangay San Vicente – currently serving</li><li><strong>Active in humanitarian outreach</strong> – began even before holding public office</li><li><strong>COVID-19 Relief Volunteer</strong> – provided assistance in Biñan and Talisay, Batangas</li></ul>', '<p class="ql-align-justify"><strong>SK Alonzo Kyne Santarin Garcia </strong>was born on December 10, 2003, at Biñan Doctor’s Hospital and currently resides on J. Gonzales Street, Barangay San Vicente, Biñan City. He is the second of three children of Albert Zarraga Garcia and Sharon Kay Capili Santarin. Coming from a service-oriented and well-respected family rooted in both local business and public service, Alonzo is the grandson of Boy “Mangkok” Garcia and Aida Zarraga, and the nephew of Hon. Alvin Garcia, a former City Councilor of Biñan. He is currently a third-year student at De La Salle University-Manila, pursuing a Bachelor of Science in Business Management. Immersed in a family of entrepreneurs and civic-minded leaders, Alonzo has grown into a young leader known for his compassion, responsibility, and deep commitment to serving others.</p>', '<ul><li><strong>Top 3 Most Outstanding Sangguniang Kabataan in Biñan</strong> – OSKAR 2024</li><li><strong>Special Citation Awards</strong> – Global Mobility, Economic Empowerment, Social Inclusion &amp; Equity (OSKAR 2024)</li><li><strong>Silver Seal Award</strong> – <em>Pagsusumikap sa Modelong Paggogobyerno</em>, at the Pambansang Sagisag ng Modelong Paggogobyerno 2024 (held on September 5, 2024)</li></ul><p><br></p>', NULL, 'ACTIVE'),
	(36, 'Hon. Liza L. Cardeño', 'CITY COUNCILOR', '1753084385_62ff234d1d2cc3c05801.jpg', '2025-07-21 07:53:05', '2025-07-31 00:44:44', 2, '<ul><li><strong>2013–2021</strong> – Served as <strong>City Councilor of Biñan City</strong> for three consecutive terms (9 years)</li><li><strong>2016</strong> – Elected as <strong>Biñan’s No. 1 Councilor</strong>; became <strong>Majority Floor Leader</strong></li><li><strong>2020–2023</strong> – Served as <strong>School President</strong> of Lakeshore Educational Institution</li><li><strong>Former President</strong>, <strong>Biñan Public Market Stallholders Association</strong></li><li><strong>Former President</strong>, <strong>League of Biñan Leaders</strong></li></ul><p><br></p>', '<p class="ql-align-justify"><strong>Konsehala Liza Lopez Cardeño</strong> was born on December 30, 1957, and is a lifelong resident of Biñan City. She is the daughter of Conrado Miranda Lopez and Filomena Benjamin Caravana, and was raised with deep-rooted values of civic responsibility, community service, and compassion—principles that have guided both her public and private life. A proud alumna of Lakeshore Educational Institution, she later served as its Alumni Association President and as the School President from 2020 to 2023. She earned her degree in BS Commerce, major in Accountancy, from the University of Santo Tomas and is a Certified Public Accountant. Before her entry into politics, she worked for over a decade in finance, accounting, and administration. She also ran “Liza’s RTW,” a well-known ready-to-wear clothing business in the Biñan Public Market, where her advocacy for market vendors led her to serve as President of the Biñan Public Market Stallholders Association. Known for her strong community spirit, she has long been active in civic organizations such as the Biñan Lions Club and the League of Biñan Leaders. Her compassionate and people-centered leadership continues to make her a respected and trusted figure in Biñan’s public life.</p>', '<ul><li><strong>Rookie of the Year</strong> – Biñan Lions Club</li><li><strong>Lion of the Year</strong> – Biñan Lions Club</li><li><strong>President</strong> – Biñan Bayanihan Lions Club</li><li><strong>Zone Chairperson</strong> and <strong>Region Chairperson</strong> – Lions District 301-A2</li><li><strong>Melvin Jones Fellow</strong> – Lions Clubs International</li><li>Recognized for legislative work in:</li><li class="ql-indent-1"><strong>Rules and Legislation</strong></li><li class="ql-indent-1"><strong>Education</strong></li><li class="ql-indent-1"><strong>Family and Women</strong></li><li class="ql-indent-1"><strong>Finance</strong></li><li class="ql-indent-1"><strong>Market and Cooperatives</strong></li></ul><p><br></p>', NULL, 'ACTIVE'),
	(37, 'Hon. Donna Yacto', 'CITY COUNCILOR', '1753084422_665d5e3c85baeb3cc9f1.jpg', '2025-07-21 07:53:42', '2025-07-31 00:44:55', 3, '<ul><li><strong>2010</strong> – Began community outreach through a <strong>feeding program</strong> in a Biñan resettlement area</li><li><strong>2016</strong> – Elected as <strong>City Councilor</strong> of Biñan</li><li class="ql-indent-1">Launched <em>Daupang Yatco</em> and <em>Go Share Jesus Movement</em></li><li class="ql-indent-1">Introduced 5 significant ordinances focusing on:</li><li class="ql-indent-3">Senior citizen support</li><li class="ql-indent-3">Teaching and non-teaching staff incentives</li><li class="ql-indent-3">Free ambulance use</li><li class="ql-indent-3">Medical access without deposit at Ospital ng Biñan</li><li class="ql-indent-3">Live streaming of city council sessions</li><li><strong>2017</strong> – Founded the <strong>Go Share Jesus Movement</strong></li><li><strong>2018 onward</strong> – Continued providing free medical, social, and spiritual support to thousands of Biñanenses</li><li><strong>2025</strong> – Re-elected as <strong>City Councilor</strong>, the <strong>lone opposition</strong> in the 7th Council of Biñan</li></ul><p><br></p>', '<p class="ql-align-justify"><strong>Hon. Donna Yatco</strong> is a well-educated and service-driven public servant from Biñan City. She holds a Master in Entrepreneurship from the prestigious Asian Institute of Management, where she graduated with the highest distinction of Superior Performance. She earned her Bachelor of Science in Biology from De La Salle University and completed both her elementary and high school education at Poveda Learning Center. Donna is the youngest of four siblings, born to Dr. Ruben Belizario Yatco, a well-respected physician from Biñan, Laguna, and Adelaida Reyes Ponce, a successful businesswoman from Calumpit, Bulacan. Deeply rooted in her faith, she has long been involved in Christian ministry work as a consistent contributor to the Jesus the Ultimate Savior (JTUS) ministry. Known for her compassion and leadership, she has initiated various outreach programs such as regular feeding for street children, spiritual support for inmates and their families, and Bible study fellowships, particularly for women. Her unwavering commitment to faith, family, and public service continues to define her life’s mission to serve the people of Biñan with integrity and purpose.</p>', '<ul><li>Completed <strong>Master in Entrepreneurship</strong> with <strong>Superior Performance</strong> distinction</li><li><strong>Over 10,000 beneficiaries</strong> reached through outreach and medical missions</li><li>Programs funded mostly by <strong>personal and family resources</strong></li><li>Honored for:</li><li class="ql-indent-1">Advocacy work for the poor and underserved</li><li class="ql-indent-1">Leadership in civic and spiritual programs</li><li class="ql-indent-1">Persistent legislative efforts despite political opposition</li></ul><p><br></p>', '1753251400_eddd8d083389f522b545.jpg,1753251400_485b4c62aace4f02f168.jpg,1753251400_19df832d621f28edae2e.jpg', 'ACTIVE'),
	(38, 'Hon. Rommel "Mel" R. Dicdican', 'CITY COUNCILOR', '1753084663_e3bcd5569e63bcd451b2.jpg', '2025-07-21 07:57:43', '2025-07-31 00:43:54', NULL, '<ul><li><strong>Current Position</strong>: Biñan City Councilor</li><li><strong>Committee Chairmanships</strong>:</li><li class="ql-indent-1">Police Matters</li><li class="ql-indent-1">Public Welfare and Safety</li><li class="ql-indent-1">Public Works and Infrastructure</li><li><strong>Co-Chairman</strong>:</li><li class="ql-indent-1">Barangay Affairs Committee</li><li><strong>Advocacies</strong>:</li><li class="ql-indent-1">Peace and Order</li><li class="ql-indent-1">Anti-drug campaigns</li><li class="ql-indent-1">Post-pandemic recovery programs</li><li class="ql-indent-1">Capacity-building for Barangay officials, Tanods, and Safety Officers</li></ul><p>He is also an <strong>active member</strong> of the following organizations:</p><ul><li>Fraternal Order of Eagles</li><li>Triskelion Grand Fraternity</li><li>Biñan CPS Advisory Council</li><li>People’s Law Enforcement Board (PLEB)</li><li>Philippine Practical Shooting Association (PPSA)</li></ul><p><br></p>', '<p class="ql-align-justify"><strong>Councilor Rommel Dicdican</strong>, known as <strong>Konsi Mel</strong>, was born on <strong>April 23, 1976</strong>, in Barangay Mamplasan, Biñan, Laguna. He is the seventh of eleven children born to the late <strong>Felipe Almarinez Dicdican</strong> and <strong>Carmen Almendras Reyes-Dicdican</strong>, both of whom were farmers. Raised in a humble, hardworking family, he grew up embodying values of faith, resilience, and service.</p><p>He is married to <strong>Evelyn Belen Dicdican</strong>, the current Punong Barangay of Mamplasan. Together, they are blessed with three children: <strong>Mariel Ivan</strong>, <strong>Sean Aaron</strong>, and <strong>Philip Andrew</strong>.</p><p>Konsi Mel completed his elementary education at Barangay Macabling Elementary School in 1988, followed by his secondary education at Saint Michael’s College of Laguna in 1993. He earned his degree in <strong>Bachelor of Science in Commerce, Major in Management</strong> from the <strong>University of Perpetual Help System – Laguna</strong> in 1997. In 2018, he completed his <strong>Master’s Degree in Business Administration, Major in Development Management and Governance</strong> from the <strong>University of Makati</strong>.</p>', '<p><strong>SINAG KAWANI Award</strong> – awarded by TRIMEX Colleges for outstanding governance</p><p>Recognized for effective legislative performance in the <strong>Sangguniang Panlungsod</strong></p>', NULL, 'ACTIVE'),
	(39, 'Hon. Arthur R. Dimaguila', 'CITY COUNCILOR', '1753084776_3d821a873245fc3d81b5.jpg', '2025-07-21 07:59:36', '2025-07-31 00:45:06', 5, '<ul><li><strong>2018–Present</strong> – Elected as Barangay Kagawad of Barangay Malaban</li><li><strong>2022</strong> – Elected as City Councilor of Biñan</li><li><strong>2025</strong> – Re-elected as City Councilor</li></ul>', '<p class="ql-align-justify"><strong>Councilor Arthur Reyes Dimaguila</strong> was born on January 18, 1981, in a modest household to Walfredo Dimaguila Sr., a municipal electrician, and Feliciana Reyes, a hardworking laundrywoman. As the ninth of ten siblings, he grew up in a home filled with discipline, resilience, and deep familial cooperation. Poverty shaped his values, but never limited his dreams. From a young age, Arthur worked to help his family, nurturing an unwavering commitment to service, humility, and compassion. Inspired by his older brother, Atty. Arman Dimaguila, a respected lawyer and city leader, Arthur discovered his own passion for public service.</p><p>He earned a Bachelor of Arts in Psychology from La Consolacion College Biñan in 2003, equipping him with a deep understanding of human behavior and empathy—skills that continue to guide his leadership. Raised in Barangay Malaban, Arthur is known in the community for his cheerful personality, humorous spirit, and genuine concern for people. As a servant-leader, he is hands-on, proactive, and approachable in addressing the needs of his constituents, especially the poor and marginalized.</p>', '<p>Topped City Councilor elections; consistently ranked <strong>#1</strong> in voter polls</p><p>Pandemic frontliner and health protocol enforcer at the barangay level</p><p>Initiated the following barangay projects:</p><ul><li><strong>Free caskets</strong> for underprivileged families</li><li><strong>Free toilet installations</strong> for low-income households</li><li><strong>Free water pumps</strong> in areas with limited access to clean water</li><li><strong>Daily de-clogging of canals</strong> to maintain sanitation and prevent flooding</li><li><strong>Construction of bridges</strong> in flood-prone areas</li><li><strong>Swift disaster response</strong> operations: rescue, relief, and safety</li></ul><p><strong>Advocate for the oppressed</strong>: Actively responds to cases of abuse, discrimination, and violence affecting women, persons with disabilities, and marginalized residents</p>', NULL, 'ACTIVE'),
	(40, 'Hon. Joselle Titus V. Bautista', 'CITY COUNCILOR', '1753084869_cc840c6063e319ab309b.jpg', '2025-07-21 08:01:09', '2025-07-31 00:45:18', 6, '<ul><li><strong>Internship at Shell Philippines</strong> – nearly 1 year</li><li><strong>Senior Data Analyst</strong> – Shopee Philippines</li><li><strong>Full-time in Family Business</strong> – after the COVID-19 pandemic began</li><li><strong>Mang Inasal Franchisee</strong> – one of the youngest in the country</li><li><strong>Elected as City Councilor of Biñan</strong> – among the youngest to be elected</li></ul>', '<p class="ql-align-justify"><strong>Konsehal Titus “Bosseng” Bautista </strong>was born on May 2, 1996, and is one of Biñan City’s youngest elected Councilors. He is the third of five children of Joselito G. Bautista and Maria Teresa V. Bautista, both respected and successful entrepreneurs in Biñan. Raised in a household that valued excellence and integrity, Titus carried these principles into his academic and professional life. He studied at PAREF Southridge School, where he consistently held leadership roles from grade school to high school, including serving as Class President from Grade 3 to Grade 12 and Vice Chairman of the Student Council. He later pursued his education at the University of Asia and the Pacific (UA&amp;P), where he completed a Master’s Degree as a Merit Scholar for five consecutive years. He also actively participated in student organizations, athletics, and the University Student Government. Professionally, he interned at Shell Philippines, worked as a Senior Data Analyst at Shopee, and eventually joined his family’s business full-time during the pandemic. His entrepreneurial spirit led him to become one of the youngest franchisees of Mang Inasal, earning a national award for excellence in employee retention and training. With a strong passion for education, youth empowerment, and local economic growth, Konsehal Titus continues to serve his fellow Biñanenses with purpose and idealism.</p>', '<ul><li><strong>Merit Scholar</strong> – for 5 consecutive years at UA&amp;P</li><li><strong>National Franchisee Award</strong> – for Retention and Training at Mang Inasal</li><li><strong>Class President</strong> – from Grade 3 to Grade 12</li><li><strong>Vice Chairman</strong>, Student Council – PAREF Southridge</li><li><strong>University Student Government Officer</strong> – UA&amp;P</li></ul><p><br></p>', NULL, 'ACTIVE'),
	(41, 'Hon. Dr. "Elvis" L. Bedia', 'CITY COUNCILOR', '1753250487_b24d55b36693b3d8f404.jpg', '2025-07-21 08:02:01', '2025-07-31 00:46:34', 7, '<p><strong>Medical &amp; Academic Milestones:</strong></p><ul><li>1988 – Passed the Medical Board Examination.</li><li>1989 – Began formal training in Surgery.</li><li>1994 – Finished Surgery Residency and passed the Philippine Board of Surgery exam.</li><li>1996 – Became a Fellow of:</li><li class="ql-indent-1">Philippine College of Surgeons (PCS)</li><li class="ql-indent-1">Philippine Society of General Surgeons (Charter Fellow)</li><li>2002 – Requested to establish Ospital ng Biñan.</li><li>2004 – Appointed First Chief of Hospital of Ospital ng Biñan.</li><li>2007 – Became Governor for Southern Tagalog Chapter of PCS.</li><li>~2004–2020s – Over 15 years of experience as:</li><li class="ql-indent-1">Medical Director</li><li class="ql-indent-1">Chairman of the Board</li><li class="ql-indent-1">Corporate President</li><li>Management Consultant of multiple hospitals.</li><li>2020 – Played a critical leadership role during the COVID-19 pandemic.</li></ul><p><strong>Public Service:</strong></p><ul><li>2022 – Elected as Councilor of Biñan City.</li><li>2025 – Reelected to the 7th Council of Biñan.</li></ul><p><strong>Military &amp; Civic Service:</strong></p><ul><li>Commissioned as Commander (Lt. Col.) in the Philippine Coast Guard (date not specified, likely within the 2010s–2020s).</li><li>Served as Head of Aeromedical Services nationwide.</li><li>Served as Worshipful Master in at least 2 Masonic Lodges in Laguna and Cavite.</li></ul>', '<p class="ql-align-justify"><strong>Hon. Dr. Elvis Bedia</strong> is a dedicated public servant and respected medical professional currently serving as a member of the 7th Council of the City of Biñan under the National Unity Party. He is married to <strong>Ofelia Velasco</strong>, and they are proud parents of two daughters who are both practicing nurses—one in <strong>Canada</strong> and the other in the <strong>United States of America</strong>.</p><p class="ql-align-justify">Dr. Bedia completed his undergraduate degree in <strong>BS Biology</strong> at the <strong>University of Santo Tomas</strong> and pursued his medical studies at the <strong>University of Perpetual Help</strong>, where he actively participated in various academic and extracurricular activities. He was known for his involvement in school publications and medical events and was featured as an <strong>exemplary alumnus</strong> in the university magazine.</p><p class="ql-align-justify">He is also passionate about teaching and mentoring, having served as an <strong>associate professor</strong> at the University of Perpetual Help College of Medicine. Outside his medical and academic commitments, Dr. Bedia is active in civic and fraternal organizations such as the <strong>Biñan Lions Club</strong>, <strong>Tau Gamma Phi</strong>, and <strong>Freemasonry</strong>. He has served in leadership roles within these organizations and is deeply involved in community service initiatives.</p><p class="ql-align-justify">Dr. Bedia is also affiliated with the <strong>Philippine Coast Guard</strong> as a commissioned officer and holds responsibilities related to aeromedical services. His commitment to healthcare, education, and public service continues to inspire and benefit the people of Biñan and beyond.</p>', '<p><strong>Best in Thesis:</strong></p><ul><li>Thesis: <em>“The effects of steroid and Vitamin A in Cats intestine after anastomosis”</em></li><li>Won Best Thesis at:</li><li class="ql-indent-1">1st Annual Surgery Residents Paper Presentation.</li><li class="ql-indent-1">University of Perpetual Help Annual Presentation.</li></ul><p><strong>Outstanding Mason Awards:</strong></p><ul><li>2022: Named Most Outstanding Mason in Laguna.</li><li>Named one of the Top 10 Most Outstanding Masons in the Philippines by the Grand Lodge of the Philippines.</li></ul><p><strong>Academic Thesis Awards:</strong></p><ul><li>All theses from his various degrees (BS Nursing, MBA, PhD in Business Management, Master in Public Admin) were chosen as Best Thesis.</li></ul><p><strong>COVID-19 Pandemic Leadership:</strong></p><ul><li>Led the team responsible for the first-ever documented recovery from COVID-19 at Unihealth Southwoods, which went viral.</li></ul><p><strong>Exemplary Alumnus:</strong></p><ul><li>Featured in the school magazine of University of Perpetual Help as an Exemplary Alumnus.</li></ul><p><br></p>', '1753250656_5f679d65f574ccbdda0d.jpg,1753250656_b80fd46bfb5f799011de.jpg,1753250656_00bafaf2b02cf282eec6.jpg', 'ACTIVE'),
	(42, 'Hon. Elmario "Elmer" B. Dimaranan', 'CITY COUNCILOR', '1753084959_0c206bfa3a652b57150f.jpg', '2025-07-21 08:02:39', NULL, 8, '<p>-</p>', '<p>-</p>', '<p>-</p>', '', 'ACTIVE'),
	(43, 'Hon. Alexis H. Desuasido', 'CITY COUNCILOR', '1753085061_072a45447b58c46f586b.jpg', '2025-07-21 08:04:21', '2025-07-31 00:46:46', 9, '<p><strong>Vice Mayor of Biñan</strong> (1995–1997)</p><ul><li><strong>Acting Mayor</strong> (Last quarter of 1997 – May 1998)</li></ul><p><strong>Presidential Staff Officer VI</strong>, Office of the President, Malacañang (During the Arroyo administration)</p><p><strong>City Councilor of Biñan</strong>:</p><ul><li>Elected in <strong>2013</strong>, <strong>2016</strong>, and <strong>2025</strong></li><li>Ranked <strong>9th</strong> in the official 2025 COMELEC results</li></ul><p><strong>COMELEC Reinstatement</strong>:</p><ul><li>In <strong>February 2022</strong>, reinstated as <strong>12th City Councilor</strong>, replacing a disqualified official</li></ul><p><strong>Appointed Department Head</strong>:</p><ul><li><strong>City Human Settlements and Livelihood Office (CHSLO)</strong> in 2020</li><li>Reappointed after 2022 term until <strong>retirement in June 2024</strong></li></ul><p><strong>Chairperson of Committees</strong> (2025–present):</p><ul><li>Committee on Housing and Urban Development and Resettlements</li><li>Committee on Environment</li><li>Committee on Utilities</li></ul><p><br></p>', '<p class="ql-align-justify"><strong>Hon. Alexis Echit H. Desuasido </strong>is a dedicated and experienced public servant from Biñan City, Laguna. His long-standing commitment to public service has earned him the respect of both government colleagues and grassroots communities. Known for his principled leadership and unwavering focus on community welfare, Councilor Desuasido brings with him decades of experience in both executive and legislative branches. He is a native of Biñan, deeply familiar with the city’s evolving needs and challenges. Now in his return to the City Council, he continues to champion causes that directly impact the lives of Biñanenses, particularly in housing, environmental sustainability, and public utilities.</p>', '<ul><li>Led programs focused on <strong>affordable housing</strong> for informal settler families</li><li>Promoted <strong>environmental protection</strong> and sustainability projects</li><li>Advocated for the <strong>improvement of utilities and essential city services</strong></li><li>Brought <strong>executive-level experience</strong> from both local and national government roles</li><li>Widely recognized for <strong>grassroots engagement</strong> and effective local governance</li></ul><p><br></p>', NULL, 'ACTIVE'),
	(44, 'Hon. Victor "Bing" L. Cariño', 'CITY COUNCILOR', '1753085167_697f94732f91231b879c.jpg', '2025-07-21 08:06:07', '2025-07-31 00:47:00', 10, '<ul><li><strong>2022–Present</strong> – City Councilor, Biñan (Second Term)</li></ul>', '<p class="ql-align-justify"><strong>Councilor Victor L. Cariño</strong>, fondly known as "Konsehal Bing," was born on September 25, 1971, and is a proud native son of Biñan. He is the second of three children of Vergel Cariño Sr. and Magdalena Laurito, a dedicated teacher. He pursued his education at the Lyceum of the Philippines University, taking up a Bachelor of Science in Electronic Communication Engineering.</p><p>Councilor Bing currently serves his second term as a City Councilor of Biñan. His life is a testament to perseverance and hard work. Raised beside the railroad tracks and once working as a porter and tricycle driver, he has risen through determination and grit. From these humble beginnings, he eventually ventured into entrepreneurship, establishing several companies in the fields of metal plating, precision tooling, fabrication, air-conditioning, and trading. He proudly calls himself <strong>“a poor man with a dream.”</strong></p>', '<p>-</p>', NULL, 'ACTIVE'),
	(45, 'Hon. Ingrid Kathrina L. Almeda', 'CITY COUNCILOR', '1753085240_c5990f3ad94929fed814.jpg', '2025-07-21 08:07:20', '2025-07-31 00:47:11', 11, '<ul><li><strong>SK Chairwoman of Barangay Poblacion</strong> (2018–2023)</li><li><strong>Intern</strong> at the Biñan Congressional Office (2023)</li><li><strong>Graduated as a scholar</strong> in 2024 while serving as <strong>varsity team captain</strong></li><li><strong>Elected City Councilor of Biñan</strong> in <strong>2025</strong></li></ul>', '<p class="ql-align-justify"><strong>Hon. Ingrid Kathrina L. Almeda</strong>, born on July 16, 1997, is the second child of Bobby and Mary Beth Almeda, both known for their lifelong generosity and compassion. However, it was her grandmother’s quiet strength and unconditional love that made the most lasting impression on her — shaping her character and heart for public service. Raised with values rooted in kindness and service, Ingrid took her first steps in education at Colegio San Agustin in Makati and later pursued a degree in Business Management, majoring in Operations Management. She graduated as a scholar in 2024, balancing academic excellence with her roles as a student-athlete, varsity team captain, and SK Chairwoman of Barangay Poblacion. Ingrid is widely known as “Ms. Congeniality,” admired for her approachable nature, inclusive mindset, and strong belief that genuine service must uplift and empower all sectors of society. Outside of politics, she has worked with her father at Intelco and professionally served at Data Lake Inc., a company focused on expanding digital access through satellite technology. She is also the granddaughter of former Councilor Kikoy Almeda and a descendant of General Mateo Capinpin — a legacy she continues to honor with integrity and purpose.</p>', '<ul><li>Established the <strong>first SK Library</strong> in Barangay Poblacion — a hub for learning, creativity, and connection</li><li>Championed <strong>inclusive SK programs</strong> that supported <strong>youth, seniors</strong>, and <strong>multi-generational learners</strong></li><li>Advocated for <strong>community-centered digital connectivity</strong>, especially in underserved barangays</li><li>Promotes <strong>inclusive policymaking</strong> for <strong>women, LGBTQIA+</strong>, <strong>senior citizens</strong>, <strong>PWDs</strong>, and <strong>digitally underconnected communities</strong></li></ul><p><br></p>', NULL, 'ACTIVE'),
	(46, 'Hon. Christopher "Toppe" A. Alba', 'CITY COUNCILOR', '1770878916_b1e08558c720ec018823.jpg', '2025-07-23 06:43:37', '2026-02-12 06:48:36', 12, '<ul><li><strong>1990</strong> – Elected President of 24K (Kongreso ng Kabataan)</li><li><strong>1993–2002</strong> – SK Chairman, served two consecutive terms</li><li><strong>2004</strong> – Elected Barangay Kagawad, Brgy. Dela Paz</li><li><strong>2007–2010</strong> – Elected Barangay Captain</li><li><strong>Post-2010</strong> – Held city government roles (Administrator, Officer, Manager)</li><li><strong>2022</strong> – Elected as City Councilor, ranked 5th out of 12</li><li><strong>2025</strong> – Serving second term as City Councilor, ranked 10th</li></ul><p><br></p>', '<p class="ql-align-justify"><strong>Councilor Christopher Alonde Alba</strong>, popularly known as “Toppe,” and sometimes still referred to as “Kap,” “Chairman,” or now “Konsi Toppe,” is the second of three children of Marcelino Alba from San Ildefonso, Bulacan, and Virginia Alonde, a native of Barangay Dela Paz, Biñan, Laguna. He grew up as a devoted church servant alongside his older brother Eric and younger sibling Marvin, serving as an altar boy and one of the lead singers of the choir at Señora Dela Paz Y Buenviaje Parish. His upbringing in a faith-driven family, with both parents also serving the church, deeply influenced his values and character. He completed his elementary education at the Dela Paz Elementary School and high school at St. Michael’s College of Laguna, where he became Central Student Council President and received a Leadership Award upon graduation. He later earned his college degree in AB Communication from the University of Perpetual Help System of Laguna, where he also served as Vice President of his department’s student body. Before fully entering public service, he worked as a teacher at various schools including Colegio San Antonio, Biñan National High School, Trimex Colleges, and APECS.</p>', '<ul><li>Leadership Award (St. Michael’s College of Laguna)</li><li>Outstanding Alumni in Public Service (SMCL)</li><li>Outstanding Punong Barangay</li><li>Child-Friendly Barangay Awardee (Three consecutive years: 2007–2010)</li><li>Recognized for establishing:</li><li class="ql-indent-1">Lingkod Kabataan</li><li class="ql-indent-1">Free mineral water supply in Brgy. Dela Paz</li><li class="ql-indent-1">Barangay E-Library with free internet for students</li><li class="ql-indent-1">Strengthened Katarungang Pambarangay</li><li class="ql-indent-1">Promotion of Biñan products in national trade fairs</li><li>Invited speaker at Ateneo de Manila University for Best Practices in Child Protection</li><li>Provided free funeral services for underprivileged barangay residents</li></ul><p><br></p>', NULL, 'ACTIVE'),
	(47, 'Hon. Angelo "Gel" B. Alonte', 'CITY MAYOR', '1753921912_9e57c1101fbbccab6d7f.jpg', '2025-07-31 00:31:52', NULL, NULL, '<p>-</p>', '<p>-</p>', '<p>-</p>', '', 'ACTIVE');
